CREATE TABLE r1_member_roles(tenant_id TEXT NOT NULL,member_id TEXT NOT NULL,role_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT,active INTEGER NOT NULL,PRIMARY KEY(tenant_id,member_id,role_id));
CREATE TABLE r1_role_permission_grants(tenant_id TEXT NOT NULL,id TEXT NOT NULL,role_id TEXT NOT NULL,object_type TEXT NOT NULL,action TEXT NOT NULL,relation_type TEXT NOT NULL,scope TEXT NOT NULL,fields TEXT NOT NULL,history_mode TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT,PRIMARY KEY(tenant_id,id));
CREATE TRIGGER r1_member_roles_insert AFTER INSERT ON r1_member_roles BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=NEW.tenant_id; END;
CREATE TRIGGER r1_member_roles_update AFTER UPDATE ON r1_member_roles BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=NEW.tenant_id; END;
CREATE TRIGGER r1_member_roles_delete AFTER DELETE ON r1_member_roles BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=OLD.tenant_id; END;
CREATE TRIGGER r1_role_grants_insert AFTER INSERT ON r1_role_permission_grants BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=NEW.tenant_id; END;
CREATE TRIGGER r1_role_grants_update AFTER UPDATE ON r1_role_permission_grants BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=NEW.tenant_id; END;
CREATE TRIGGER r1_role_grants_delete AFTER DELETE ON r1_role_permission_grants BEGIN UPDATE r1_schema_state SET authorization_revision=authorization_revision+1 WHERE tenant_id=OLD.tenant_id; END;
CREATE TABLE r1_portal_invalidations(tenant_id TEXT NOT NULL,source TEXT NOT NULL,source_id TEXT NOT NULL,event_id TEXT NOT NULL,source_revision INTEGER NOT NULL,workspace_revision INTEGER NOT NULL,PRIMARY KEY(tenant_id,source,source_id));
CREATE TABLE r1_portal_cursors(tenant_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,query_digest TEXT NOT NULL,source_digest TEXT NOT NULL,authorization_revision INTEGER NOT NULL,writer_epoch INTEGER NOT NULL,recovery_epoch INTEGER NOT NULL,last_key TEXT NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
